// Box Box: push every box onto a goal. Standard Sokoban notation:
//   # wall   @ player   + player on goal   $ box   * box on goal   . goal   (space) floor
// Levels are original (hand-made or generated by pulling boxes backwards from a solved
// position); tests/puzzles.test.mjs proves each one solvable. Sorted easiest first.

export const LEVELS = [
  ['#####', '#@$.#', '#####'],
  ['######', '#    #', '# $$ #', '#@.. #', '######'],
  ['  ####', '###  #', '#  $ #', '# #. #', '#@ $.#', '######'],
  ['#######', '#     #', '# $#$ #', '# .@. #', '#######'],
  ['#######', '#.  ..#', '# $$ $#', '#  @  #', '#######'],
  ['  ####', '  #  #', '### .#', '# $  #', '# @$.#', '##   #', ' #####'],
  ['#######', '#.@ # #', '#$* $ #', '#   $ #', '# ..  #', '#  *  #', '#######'],
  [' ######', '##    #', '#  ## #', '# $ $ #', '#.@ ..#', '# $ ###', '#   #', '#####'],
  ['  ######', '### .  #', '# $ #$ #', '#@#    #', '#    ###', '###. #', '  ####'],
  ['########', '# $  .*#', '# ####*#', '#      #', '## ## ##', '# $    #', '# @#.  #', '########'],
  ['########', '#@.    #', '# ##   #', '#  * # #', '# $# $ #', '#.     #', '########'],
  ['########', '#    . #', '# ##   #', '# .$ # #', '# $# @ #', '#      #', '########'],
  ['#########', '# . #   #', '#  $    #', '##@#*# ##', '#    $  #', '#.  #   #', '#########'],
  ['########', '#.   $ #', '# #### #', '#      #', '##$## ##', '# *    #', '#@.#   #', '########'],
  ['#########', '#.  # . #', '#    $  #', '##$#$#.##', '# $@    #', '#.  #   #', '#########'],
  [' #######', '##@    #', '# $# #.#', '#   .  #', '#.#$#$ #', '#     ##', '#######'],
];

/** Parse a level into { w, h, walls:Set, goals:Set, boxes:Set, player } using index = y*w+x. */
export function parse(rows) {
  const h = rows.length;
  const w = Math.max(...rows.map((r) => r.length));
  const walls = new Set(); const goals = new Set(); const boxes = new Set();
  let player = -1;
  rows.forEach((row, y) => {
    for (let x = 0; x < w; x++) {
      const ch = row[x] ?? ' ';
      const i = y * w + x;
      if (ch === '#') walls.add(i);
      if ('.+*'.includes(ch)) goals.add(i);
      if ('$*'.includes(ch)) boxes.add(i);
      if ('@+'.includes(ch)) player = i;
    }
  });
  return { w, h, walls, goals, boxes, player };
}

/** Floor cells reachable from the player (used to draw only the inside of the level). */
export function interior(lv) {
  const seen = new Set([lv.player]);
  const stack = [lv.player];
  while (stack.length) {
    const i = stack.pop();
    for (const d of [-1, 1, -lv.w, lv.w]) {
      const n = i + d;
      if (n < 0 || n >= lv.w * lv.h || lv.walls.has(n) || seen.has(n)) continue;
      if ((d === 1 && n % lv.w === 0) || (d === -1 && i % lv.w === 0)) continue;
      seen.add(n); stack.push(n);
    }
  }
  return seen;
}

export const DIRS = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] };

/** Try to move. Returns { player, boxes, pushed } or null if blocked. */
export function step(lv, state, dir) {
  const [dx, dy] = DIRS[dir];
  const px = state.player % lv.w; const py = Math.floor(state.player / lv.w);
  const nx = px + dx; const ny = py + dy;
  if (nx < 0 || ny < 0 || nx >= lv.w || ny >= lv.h) return null;
  const n = ny * lv.w + nx;
  if (lv.walls.has(n)) return null;
  if (state.boxes.has(n)) {
    const bx = nx + dx; const by = ny + dy;
    const b = by * lv.w + bx;
    if (bx < 0 || by < 0 || bx >= lv.w || by >= lv.h || lv.walls.has(b) || state.boxes.has(b)) return null;
    const boxes = new Set(state.boxes); boxes.delete(n); boxes.add(b);
    return { player: n, boxes, pushed: { from: n, to: b } };
  }
  return { player: n, boxes: state.boxes, pushed: null };
}

export const solved = (lv, state) => [...state.boxes].every((b) => lv.goals.has(b));

/** Breadth-first solver (moves). Returns the move count of the shortest solution, or -1. */
export function solve(rows, limit = 400000) {
  const lv = parse(rows);
  const key = (s) => `${s.player}|${[...s.boxes].sort((a, b) => a - b).join(',')}`;
  let frontier = [{ player: lv.player, boxes: lv.boxes }];
  const seen = new Set([key(frontier[0])]);
  for (let depth = 0; frontier.length && seen.size < limit; depth++) {
    const next = [];
    for (const s of frontier) {
      if (solved(lv, s)) return depth;
      for (const d of Object.keys(DIRS)) {
        const r = step(lv, s, d);
        if (!r) continue;
        const k = key(r);
        if (seen.has(k)) continue;
        seen.add(k); next.push(r);
      }
    }
    frontier = next;
  }
  return -1;
}
